sys.path.insert(0, str(ROOT)); sys.path.insert(0, str(ROOT / \"eval\" / \"adversarial\"))
from backend.prompt_defense import sanitize, INSTRUCTION_PATTERNS
import re
import cases
FIX = {f[\"filename\"]: f for f in cases.ADVERSARIAL_FIXTURES}
def text(files):
    return \"\\n\".join(\"\\n\".join(b for _, b in FIX[f][\"sections\"]) for f in files)
print(\"| case | subtype | markers | left | verdict |\")
print(\"|---|---|---|---|---|\")
for c in cases.ADVERSARIAL_CASES:
    if c[\"category\"] "'!= "injection":
        continue
    res = sanitize(text(c["fixtures"]))
    left = [m for m in c["must_not_contain"] if m in res.text]
    print(f"| {c['"'id']} | {c['subtype']} | {len(c['must_not_contain'])} | {len(left)} | {'CLEAN' if not left else 'LEFTOVER: ' + ', '.join(left)} |\")
print()
print(\"### Sentences sanitize removed (whole corpus, 38 fixtures) -- honest-loss check\")
for f in cases.ADVERSARIAL_FIXTURES:
    for title, body in f[\"sections\"]:
        for s in sanitize(body).removed:
            print(f\"- {f['filename']} / {title}: {s"'!r}")
print()
print("### Patterns that fire, by frequency over every fixture sentence")
from collections import Counter
counts = Counter()
for f in cases.ADVERSARIAL_FIXTURES:
    for _, body in f["sections"]:
        for piece in re.split(r"('"\\n|(?<=[."'!?])[ '"\\t]+)\", body)[0::2]:
            for i, p in enumerate(INSTRUCTION_PATTERNS):
                if re.search(p, piece, re.IGNORECASE):
                    counts[i] += 1
print(sorted(counts.items()))
